15	#include "sram_backdoor.h"
16	
17	#include <algorithm>
18	#include <cstdio>
19	#include <cstring>
20	#include <map>
21	#include <random>
22	#include <vector>
23	
24	#include "svdpi.h"
25	
26	namespace coralnpu {
27	namespace {
28	
29	struct BackdoorSram {
30	  std::vector<uint8_t> data;
31	  uint64_t global_addr;
32	  uint32_t width_bytes;
33	};
34	
35	std::map<uint64_t, BackdoorSram *> registered_srams;
36	
37	bool ApplyLoadToSram(BackdoorSram &sram, uint64_t load_addr,
38	                     const uint8_t *data, size_t len) {
39	  uint64_t load_end = load_addr + len;
40	  uint64_t sram_end = sram.global_addr + sram.data.size();
41	
42	  if (load_end <= sram.global_addr || load_addr >= sram_end) {
43	    return false;
44	  }
45	
46	  uint64_t start = std::max(load_addr, sram.global_addr);
47	  uint64_t end = std::min(load_end, sram_end);
48	  uint64_t copy_len = end - start;
49	  uint64_t sram_offset = start - sram.global_addr;
50	  uint64_t data_offset = start - load_addr;
51	
52	  std::memcpy(sram.data.data() + sram_offset, data + data_offset, copy_len);
53	  return true;
54	}
55	
56	void *RegisterSram(uint64_t global_addr, size_t size_bytes,
57	                   uint32_t width_bytes) {
58	  BackdoorSram *sram = new BackdoorSram;
59	  sram->global_addr = global_addr;
60	  sram->data.resize(size_bytes);
61	  sram->width_bytes = width_bytes;
62	
63	  // Randomize memory content for simulation.
64	  std::random_device rd;
65	  std::mt19937 gen(rd());
66	  std::uniform_int_distribution<> dis(0, 255);
67	  for (size_t i = 0; i < size_bytes; ++i) {
68	    sram->data[i] = dis(gen);
69	  }
70	
71	  registered_srams[global_addr] = sram;
72	
73	  return sram;
74	}
75	
76	// Simple ELF parsing structures
77	struct Elf32_Ehdr {
78	  unsigned char e_ident[16];
79	  uint16_t e_type;
80	  uint16_t e_machine;
81	  uint32_t e_version;
82	  uint32_t e_entry;
83	  uint32_t e_phoff;
84	  uint32_t e_shoff;
85	  uint32_t e_flags;
86	  uint16_t e_ehsize;
87	  uint16_t e_phentsize;
88	  uint16_t e_phnum;
89	  uint16_t e_shentsize;
90	  uint16_t e_shnum;
91	  uint16_t e_shstrndx;
92	};
93	
94	struct Elf32_Phdr {
95	  uint32_t p_type;
96	  uint32_t p_offset;
97	  uint32_t p_vaddr;
98	  uint32_t p_paddr;
99	  uint32_t p_filesz;
100	  uint32_t p_memsz;
101	  uint32_t p_flags;
102	  uint32_t p_align;
103	};
104	
105	#define PT_LOAD 1
106	
107	} // namespace
108	
109	bool SramBackdoorLoad(uint64_t global_addr, const uint8_t *data, size_t len) {
110	  bool load_ok = false;
111	  // Sweep all SRAMs, until we find the correct one or exhaust our options.
112	  for (const auto &[base, sram] : registered_srams) {
113	    if (ApplyLoadToSram(*sram, global_addr, data, len)) {
114	      load_ok = true;
115	    }
116	  }
117	  return load_ok;
118	}
119	
120	} // namespace coralnpu
121	
122	extern "C" {
123	using namespace coralnpu;
124	
125	void *sram_init(uint64_t global_addr, uint64_t size_bytes,
126	                uint32_t width_bytes) {
127	  return RegisterSram(global_addr, size_bytes, width_bytes);
128	}
129	
130	void sram_read(void *handle, uint32_t addr, svBitVecVal *data) {
131	  BackdoorSram *sram = static_cast<BackdoorSram *>(handle);
132	  size_t offset = (size_t)addr * sram->width_bytes;
133	  if (offset + sram->width_bytes <= sram->data.size()) {
134	    std::memcpy(data, sram->data.data() + offset, sram->width_bytes);
135	  }
136	}
137	
138	void sram_write(void *handle, uint32_t addr, const svBitVecVal *data,
139	                uint32_t wmask) {
140	  BackdoorSram *sram = static_cast<BackdoorSram *>(handle);
141	  size_t offset = (size_t)addr * sram->width_bytes;
142	  if (offset + sram->width_bytes <= sram->data.size()) {
143	    uint8_t *dest = sram->data.data() + offset;
144	    const uint8_t *src = reinterpret_cast<const uint8_t *>(data);
145	    for (size_t i = 0; i < sram->width_bytes; ++i) {
146	      if ((wmask >> i) & 1) {
147	        dest[i] = src[i];
148	      }
149	    }
150	  }
151	}
152	
153	void sram_cleanup(void *handle) {
154	  if (!handle)
155	    return;
156	  BackdoorSram *sram = static_cast<BackdoorSram *>(handle);
157	  registered_srams.erase(sram->global_addr);
158	  delete sram;
159	}
160	
161	bool sram_backdoor_load_c(uint64_t global_addr, const uint8_t *data,
162	                          size_t len) {
163	  return SramBackdoorLoad(global_addr, data, len);
164	}
165	
166	void sram_load_elf(const char *filename) {
167	  FILE *f = std::fopen(filename, "rb");
168	  if (!f) {
169	    std::fprintf(stderr, "[SRAM Backdoor] Failed to open ELF file: %s\n",
170	                 filename);
171	    return;
172	  }
173	
174	  Elf32_Ehdr ehdr;
175	  if (std::fread(&ehdr, sizeof(ehdr), 1, f) != 1) {
176	    std::fprintf(stderr, "[SRAM Backdoor] Failed to read ELF header: %s\n",
177	                 filename);
178	    std::fclose(f);
179	    return;
180	  }
181	
182	  // Check ELF magic
183	  if (std::memcmp(ehdr.e_ident, "\x7f\x45\x4c\x46", 4) != 0) {
184	    std::fprintf(stderr, "[SRAM Backdoor] Invalid ELF magic: %s\n", filename);
185	    std::fclose(f);
186	    return;
187	  }
188	
189	  std::fseek(f, ehdr.e_phoff, SEEK_SET);
190	  std::vector<Elf32_Phdr> phdrs(ehdr.e_phnum);
191	  if (std::fread(phdrs.data(), sizeof(Elf32_Phdr), ehdr.e_phnum, f) !=
192	      ehdr.e_phnum) {
193	    std::fprintf(stderr, "[SRAM Backdoor] Failed to read program headers: %s\n",
194	                 filename);
195	    std::fclose(f);
196	    return;
197	  }
198	
199	  for (const auto &phdr : phdrs) {
200	    if (phdr.p_type == PT_LOAD && phdr.p_filesz > 0) {
201	      std::vector<uint8_t> buffer(phdr.p_filesz);
202	      std::fseek(f, phdr.p_offset, SEEK_SET);
203	      if (std::fread(buffer.data(), 1, phdr.p_filesz, f) != phdr.p_filesz) {
204	        std::fprintf(stderr,
205	                     "[SRAM Backdoor] Failed to read segment data: %s\n",
206	                     filename);
207	        continue;
208	      }
209	
210	      SramBackdoorLoad(phdr.p_paddr, buffer.data(), buffer.size());
211	    }
212	  }
213	
214	  std::fclose(f);
215	}
216	}
