// 3:2 compressor (full adder chain).
module compressor_3_2 #(
    parameter int W = 32
) (
    input  wire [W-1:0] a,
    input  wire [W-1:0] b,
    input  wire [W-1:0] c,
    output wire [W-1:0] sum,
    output wire [W-1:0] carry
