// Copyright 2026 Google LLC
// SPDX-License-Identifier: Apache-2.0
//
// Constant-function math helpers used by FPnew/common_cells.
package cf_math_pkg;

  function automatic integer ceil_div(input integer a, input integer b);
    ceil_div = (a + b - 1) / b;
  endfunction

  function automatic integer idx_width(input integer n);
    idx_width = (n > 1) ? $clog2(n) : 1;
  endfunction

endpackage

// Copyright 2026 Google LLC
// SPDX-License-Identifier: Apache-2.0
//
// Leading zero counter (or trailing zero when MODE=1). Simple loop-based
// implementation suitable for simulation.
module lzc #(
    parameter int unsigned WIDTH = 8,
    parameter bit          MODE  = 1'b0   // 0: count leading; 1: count trailing
) (
    input  wire [WIDTH-1:0]                   in_i,
    output reg  [$clog2(WIDTH > 1 ? WIDTH : 2)-1:0] cnt_o,
    output reg                                empty_o
);
  integer i;
  always @(*) begin
    cnt_o   = '0;
    empty_o = 1'b1;
    if (MODE == 1'b0) begin
      // Count leading zeros (from MSB).
      for (i = WIDTH-1; i >= 0; i = i - 1) begin
        if (empty_o && in_i[i]) begin
          cnt_o   = (WIDTH-1-i);
          empty_o = 1'b0;
        end
      end
    end else begin
      // Count trailing zeros (from LSB).
      for (i = 0; i < WIDTH; i = i + 1) begin
        if (empty_o && in_i[i]) begin
          cnt_o   = i;
          empty_o = 1'b0;
        end
      end
    end
  end
endmodule

// Copyright 2026 Google LLC
// SPDX-License-Identifier: Apache-2.0
//
// Round-robin arbiter tree (simplified). Picks among NumIn req lines and
// outputs grant + arbitrated data.
module rr_arb_tree #(
    parameter int unsigned NumIn     = 4,
    parameter int unsigned DataWidth = 32,
    parameter type         DataType  = logic [DataWidth-1:0],
    parameter bit          AxiVldRdy = 1'b0,
    parameter bit          LockIn    = 1'b0,
    parameter bit          FairArb   = 1'b1,
    parameter int unsigned IdxWidth  = (NumIn > 1) ? $clog2(NumIn) : 1
) (
    input  wire                       clk_i,
    input  wire                       rst_ni,
    input  wire                       flush_i,
    input  wire [IdxWidth-1:0]        rr_i,
    input  wire [NumIn-1:0]           req_i,
    output reg  [NumIn-1:0]           gnt_o,
    input  wire [NumIn-1:0][DataWidth-1:0] data_i,
    output wire                       req_o,
    input  wire                       gnt_i,
    output reg  [DataWidth-1:0]       data_o,
    output reg  [IdxWidth-1:0]        idx_o
);
  (* unused *) wire _flush_unused = flush_i;
  (* unused *) wire _rri_unused   = |rr_i;

  reg [IdxWidth-1:0] ptr_q;
  integer i;

  always @(*) begin
    gnt_o  = '0;
    data_o = '0;
    idx_o  = '0;
    for (i = 0; i < NumIn; i = i + 1) begin
      if (gnt_o == '0) begin
        if (req_i[(ptr_q + i) % NumIn]) begin
          gnt_o[(ptr_q + i) % NumIn] = 1'b1;
          data_o = data_i[(ptr_q + i) % NumIn];
          idx_o  = (ptr_q + i) % NumIn;
        end
      end
    end
  end

  assign req_o = |req_i;

  always @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      ptr_q <= '0;
    end else if (req_o && gnt_i) begin
      ptr_q <= idx_o + 1'b1;
    end
  end
endmodule

// Copyright 2026 Google LLC
// SPDX-License-Identifier: Apache-2.0
//
// Minimal FPnew package (subset of pulp-platform/fpnew).
package fpnew_pkg;

  typedef enum logic [2:0] {
    FP32    = 3'b000,
    FP64    = 3'b001,
    FP16    = 3'b010,
    FP8     = 3'b011,
    FP16ALT = 3'b100,
    FP8ALT  = 3'b101
  } fp_format_e;

  typedef enum logic [1:0] {
    INT8  = 2'b00,
    INT16 = 2'b01,
    INT32 = 2'b10,
    INT64 = 2'b11
  } int_format_e;

  typedef enum logic [3:0] {
    FMADD, FNMSUB, ADD, MUL,
    DIV, SQRT,
    SGNJ, MINMAX, CMP, CLASSIFY,
    F2F, F2I, I2F, CPKAB, CPKCD
  } operation_e;

  typedef enum logic [2:0] {
    RNE = 3'b000,
    RTZ = 3'b001,
    RDN = 3'b010,
    RUP = 3'b011,
    RMM = 3'b100,
    DYN = 3'b111
  } roundmode_e;

  typedef enum logic [2:0] {
    NEGINF, NEGNORM, NEGSUBNORM, NEGZERO,
    POSZERO, POSSUBNORM, POSNORM, POSINF
  } classmask_e;

  typedef struct packed {
    logic NV;
    logic DZ;
    logic OF;
    logic UF;
    logic NX;
  } status_t;

  typedef struct packed {
    logic is_normal;
    logic is_subnormal;
    logic is_zero;
    logic is_inf;
    logic is_nan;
    logic is_signalling;
    logic is_quiet;
    logic is_boxed;
  } fp_info_t;

  function automatic integer fp_width(input fp_format_e fmt);
    case (fmt)
      FP32:    fp_width = 32;
      FP64:    fp_width = 64;
      FP16:    fp_width = 16;
      FP8:     fp_width = 8;
      FP16ALT: fp_width = 16;
      FP8ALT:  fp_width = 8;
      default: fp_width = 32;
    endcase
  endfunction

  function automatic integer exp_bits(input fp_format_e fmt);
    case (fmt)
      FP32:    exp_bits = 8;
      FP64:    exp_bits = 11;
      FP16:    exp_bits = 5;
      FP16ALT: exp_bits = 8;
      FP8:     exp_bits = 5;
      FP8ALT:  exp_bits = 4;
      default: exp_bits = 8;
    endcase
  endfunction

  function automatic integer man_bits(input fp_format_e fmt);
    man_bits = fp_width(fmt) - exp_bits(fmt) - 1;
  endfunction

endpackage

